function curLang() {
  if (typeof S !== 'undefined' && S && S.lang) return S.lang;
  if (typeof OB !== 'undefined' && OB && OB.lang) return OB.lang;
  return 'zh';
}
function t(key, vars) {
  const s = STR[curLang()][key] ?? STR.zh[key] ?? key;
  return vars ? s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m)) : s;
}
